import os
from cryptography.hazmat.primitives import serialization,hashes
from cryptography.hazmat.primitives.asymmetric import rsa,padding
from cryptography.hazmat.primitives.ciphers.aead import AESGCM

def seal(public_pem,plaintext,aad=b''):
    if any(not isinstance(value,bytes) for value in (public_pem,plaintext,aad)):raise ValueError('bytes required')
    try:key=serialization.load_pem_public_key(public_pem)
    except (ValueError,TypeError):raise ValueError('invalid public key') from None
    if not isinstance(key,rsa.RSAPublicKey) or key.key_size<2048:raise ValueError('RSA-2048 or stronger required')
    symmetric=os.urandom(32);nonce=os.urandom(12)
    wrapped=key.encrypt(symmetric,padding.OAEP(mgf=padding.MGF1(hashes.SHA256()),algorithm=hashes.SHA256(),label=None))
    return {'wrapped_key':wrapped,'nonce':nonce,'ciphertext':AESGCM(symmetric).encrypt(nonce,plaintext,aad)}
```

