import os
import stat

def load_secret(path):
    try:descriptor=os.open(path,os.O_RDONLY|os.O_CLOEXEC|os.O_NOFOLLOW)
    except OSError:raise ValueError('secret unavailable') from None
    try:
        metadata=os.fstat(descriptor)
        if not stat.S_ISREG(metadata.st_mode) or metadata.st_uid!=os.geteuid() or stat.S_IMODE(metadata.st_mode)&0o077:raise ValueError('insecure secret file')
        data=bytearray()
        while len(data)<4097:
            part=os.read(descriptor,4097-len(data))
            if not part:break
            data.extend(part)
        if not 1<=len(data)<=4096:raise ValueError('secret size')
        try:value=bytes(data).decode('utf-8').strip()
        except UnicodeDecodeError:raise ValueError('secret encoding') from None
        if not value:raise ValueError('empty secret')
        return value
    finally:os.close(descriptor)
